import {homeProducts} from '../lib/catalog.mjs';
import {hubGuides} from '../lib/hubs.mjs';
const featured=homeProducts(products);
const heroProducts=['funeral-basic','funeral-premium','congrats-basic','congrats-premium'].map(key=>products.find(p=>p.key===key)).filter(Boolean);
---
<BaseLayout title={`${site.region} 꽃배달 | 근조·축하화환 ${site.brand}`} description={`${site.region} 근조·축하화환 상품 사진과 기본가격을 비교하세요. 보내는 마음과 예산에 맞는 꽃을 고르고 전화나 온라인으로 편하게 상담하세요.`} canonicalPath="/" socialProduct={heroProducts[0] || products[0]}>
<section class="home-hero">
 <div class="hero-copy"><span class="eyebrow">{site.region} 꽃배달 · {site.brand}</span><h1>{site.region} 꽃배달,<br/>근조·축하화환을 고르세요</h1><p>산본시장에 첫 가게를 여는 이웃, 부곡동의 새 사업장으로 옮겨가는 거래처, 한세대학교의 기쁜 행사를 준비하는 분께 응원을 전해 보세요. 군포에서 맞이하는 새로운 시작에 어울릴 축하화환을 사진과 예산으로 고르실 수 있습니다. 지샘병원 장례식장에 조용한 위로를 전하고 싶은 날에도 꽃이랑에 편하게 말씀해 주세요.</p>
 <div class="actions"><a class="btn primary" href={site.phoneHref}>☎ {site.phone} 전화주문</a><a class="btn dark" href={site.orderUrl}>온라인 주문</a></div>
 <div class="facts"><span>전화 {site.phoneOrderHours}</span><span>온라인 {site.onlineOrderHours} 접수</span><span>전달 일정·비용 상담</span></div></div>
 <div class="hero-products" aria-label="근조·축하화환 상품">{heroProducts.map((p:any)=><a class="hero-product" href={p.orderUrl} data-product-family={p.family} data-product-key={p.key}><img src={p.img} alt={p.name} loading="eager" width="420" height="420"/><span>{p.name}<strong>{p.price.toLocaleString()}원 · 상품 기본가격</strong></span></a>)}</div>
</section>
{groups.length>0 && <section class="purpose-navigation" data-purpose-navigation><div class="section-title"><span class="eyebrow">목적에 맞게 선택</span><h2>누구에게, 어디로 보내시나요?</h2></div><div class="purpose-grid">{groups.map(g=><a class="page-card purpose-card" href={g.url}><strong>{g.label}</strong><span>{hubGuides[g.cat].decision[0]}</span><em>상품·주문 준비 보기 →</em></a>)}</div></section>}
{districts.length>0 && <section class="purpose-navigation" data-region-navigation><div class="section-title"><h2>지역별 꽃배달 안내</h2><p>받는 곳의 동 이름으로 주문 안내를 찾아보세요.</p></div><div class="purpose-grid">{districts.map(district=><a class="page-card purpose-card" href={`/regions/#${district.key}`}><strong>{district.name}</strong><span>장소에 맞는 꽃 선물 안내</span></a>)}</div><a href="/regions/">지역 전체 보기 →</a></section>}
<section class="product-section" data-home-selection><div class="section-title"><span class="eyebrow">{site.brand} 상품과 가격</span><h2>근조·축하화환 상품과 가격을 비교하세요</h2><p>누구에게 어떤 인사를 전하고 싶은지 떠올리며 사진을 살펴보세요. 정해 둔 예산에서 고르셔도 좋고, 선택이 어려우시면 전화로 상품과 문구를 함께 상담하실 수 있습니다.</p></div><ProductCards products={featured}/></section>
<InlineOrderBanner/>
{groups.length>0 && <section class="hub-overview"><div class="section-title"><span class="eyebrow">장소와 상황별 상세 안내</span><h2>전달할 곳에 필요한 정보를 확인하세요</h2></div>{groups.map(g=><article class="hub-block"><div class="hub-heading"><h3>{g.label}</h3><a href={g.url}>전체 보기 →</a></div><div class="card-grid">{pages.filter((p:any)=>p.category===g.cat).map((p:any)=><a class="page-card" href={p.url}><strong>{p.primaryKeyword}</strong><span>{p.cardSummary}</span></a>)}</div></article>)}</section>}
</BaseLayout>

